1	// Test helpers: start server.mjs as a child process and talk HTTP to it.
2	import assert from 'node:assert/strict';
3	import { spawn } from 'node:child_process';
4	import { mkdtemp, rm, stat, writeFile } from 'node:fs/promises';
5	import { request as httpRequest } from 'node:http';
6	import { connect, createServer as createNetServer } from 'node:net';
7	import { tmpdir } from 'node:os';
8	import { dirname, join } from 'node:path';
9	import { fileURLToPath } from 'node:url';
10	
11	export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
12	export const SERVER = join(ROOT, 'server.mjs');
13	export const LISTEN_RE = /^listening on http:\/\/127\.0\.0\.1:(\d+)\n$/;
14	export const JSON_TYPE = 'application/json; charset=utf-8';
15	export const JSON_HEADERS = Object.freeze({ 'Content-Type': 'application/json' });
16	const EXIT_TIMEOUT_MS = 5000;
17	const LISTEN_TIMEOUT_MS = 10000;
18	const REQUEST_TIMEOUT_MS = 15000;
19	
20	/** Every error message the spec names, exactly. */
21	export const MSG = Object.freeze({
22	  internal: 'internal error',
23	  notFound: 'not found',
24	  method: 'method not allowed',
25	  bookingNotFound: 'booking not found',
26	  contentType: 'content type must be application/json',
27	  tooLarge: 'body too large',
28	  notObject: 'body must be a JSON object',
29	  room: 'room must be one of Aurora, Borealis, Cosmos',
30	  title: 'title must be 1 to 80 characters',
31	  date: 'date must be a valid YYYY-MM-DD date',
32	  start: 'start must be HH:MM',
33	  end: 'end must be HH:MM',
34	  order: 'end must be after start',
35	});
36	
37	/** Asserts an error reply: exact status, body exactly {error}, exact JSON content type. */
38	export function expectError(res, status, error) {
39	  assert.strictEqual(res.status, status, res.text);
40	  assert.deepStrictEqual(res.json, { error });
41	  assert.strictEqual(res.headers['content-type'], JSON_TYPE);
42	}
