44	let dateCounter = 0;
45	/** A date no earlier call returned (2040-01-02 onwards), so accepted bookings never overlap. */
46	export function uniqueDate() {
47	  dateCounter += 1;
48	  const month = String(1 + Math.floor(dateCounter / 28)).padStart(2, '0');
49	  const day = String(1 + (dateCounter % 28)).padStart(2, '0');
50	  return `2040-${month}-${day}`;
51	}
