74	/** Starts a server (see startServer), runs fn(server), always stops it. */
75	export async function withServer(opts, fn) {
76	  const server = await startServer(opts);
77	  try {
78	    return await fn(server);
79	  } finally {
80	    await server.stop();
81	  }
82	}
83	
84	/** A valid booking body; override any field. */
85	export const booking = (overrides = {}) => ({
86	  room: 'Aurora',
87	  title: 'Standup',
88	  date: '2026-11-03',
89	  start: '09:00',
90	  end: '10:00',
91	  ...overrides,
92	});
93	
94	export const makeTmpDir = () => mkdtemp(join(tmpdir(), 'rooms-test-'));
95	
96	/** Writes a data file in the server's layout. */
97	export const writeStore = (path, bookings = [], nextId = bookings.length + 1) =>
98	  writeFile(path, JSON.stringify({ nextId, bookings }));
99	
100	/** Environment without the caller's PORT / DATA_FILE; `undefined` values mean unset. */
101	function buildEnv(env) {
102	  const base = { ...process.env };
103	  delete base.PORT;
104	  delete base.DATA_FILE;
105	  const merged = { ...base, ...env };
106	  return Object.fromEntries(Object.entries(merged).filter(([, v]) => v !== undefined));
107	}
108	
109	/** Spawns the server. Returns a handle with live stdout/stderr text and an exit promise. */
110	export function spawnServer({ cwd, env = {}, script = SERVER }) {
111	  const child = spawn(process.execPath, [script], { cwd, env: buildEnv(env) });
112	  const out = { stdout: '', stderr: '' };
113	  child.stdout.setEncoding('utf8').on('data', (d) => (out.stdout += d));
114	  child.stderr.setEncoding('utf8').on('data', (d) => (out.stderr += d));
115	  const exited = new Promise((resolve) => {
116	    child.on('close', (code, signal) => resolve({ code, signal }));
117	  });
118	  return {
119	    child,
120	    exited,
121	    stdout: () => out.stdout,
122	    stderr: () => out.stderr,
123	  };
124	}
125	
126	/** Runs the server until it exits by itself; fails if it is still running after the timeout. */
127	export async function runToExit(opts, timeoutMs = EXIT_TIMEOUT_MS) {
128	  const handle = spawnServer(opts);
129	  let timer;
130	  const timeout = new Promise((resolve) => {
131	    timer = setTimeout(() => resolve('timeout'), timeoutMs);
132	  });
133	  const result = await Promise.race([handle.exited, timeout]);
134	  clearTimeout(timer);
135	  if (result === 'timeout') {
136	    handle.child.kill('SIGKILL');
137	    await handle.exited;
138	    throw new Error(`server did not exit; stdout=${JSON.stringify(handle.stdout())}`);
139	  }
140	  return { code: result.code, signal: result.signal, stdout: handle.stdout(), stderr: handle.stderr() };
141	}
142	
143	/**
144	 * Starts the server (PORT=0 unless given) and waits for the listening line.
145	 * Returns { port, stop(), stdout(), stderr(), child }.
146	 */
147	export async function startServer({ cwd, env = {}, script }) {
148	  const handle = spawnServer({ cwd, env: { PORT: '0', ...env }, script });
149	  const stop = async () => {
150	    if (handle.child.exitCode === null && handle.child.signalCode === null) {
151	      handle.child.kill();
152	    }
153	    await handle.exited;
154	  };
155	  let timer;
156	  try {
157	    const port = await new Promise((resolve, reject) => {
158	      handle.child.stdout.on('data', () => {
159	        const match = LISTEN_RE.exec(handle.stdout());
160	        if (match) resolve(Number(match[1]));
161	      });
162	      handle.exited.then(({ code }) =>
163	        reject(new Error(`server exited (${code}) before listening: ${handle.stderr()}`)),
164	      );
165	      timer = setTimeout(() => reject(new Error('server did not print its listening line')), LISTEN_TIMEOUT_MS);
166	    });
167	    return { ...handle, port, stop };
168	  } catch (err) {
169	    await stop();
170	    throw err;
171	  } finally {
172	    clearTimeout(timer);
173	  }
174	}
