176	/**
177	 * One HTTP request with a raw path (sent as given, nothing normalised).
178	 * `chunks` (an array of strings/Buffers) sends the body in several writes instead of `body`.
179	 * Resolves to { status, headers, text, json } (json is undefined when the body is not JSON).
180	 */
181	export function request(port, { method = 'GET', path = '/', headers = {}, body, chunks } = {}) {
182	  return new Promise((resolve, reject) => {
183	    const req = httpRequest(
184	      { host: '127.0.0.1', port, method, path, headers, agent: false, timeout: REQUEST_TIMEOUT_MS },
185	      (res) => {
186	        const chunks = [];
187	        res.on('data', (c) => chunks.push(c));
188	        res.on('end', () => {
189	          const text = Buffer.concat(chunks).toString('utf8');
190	          let json;
191	          try {
192	            json = JSON.parse(text);
193	          } catch {
194	            json = undefined;
195	          }
196	          resolve({ status: res.statusCode, headers: res.headers, text, json });
197	        });
198	        res.on('error', reject);
199	      },
200	    );
201	    req.on('error', reject);
202	    req.on('timeout', () => req.destroy(new Error(`no reply to ${method} ${path}`)));
203	    for (const chunk of chunks ?? []) req.write(chunk);
204	    req.end(body);
205	  });
206	}
207	
208	/** POST /api/bookings with a JSON body (object, or a raw string/Buffer). */
209	export function postBooking(port, value, headers = JSON_HEADERS) {
210	  const body = typeof value === 'string' || Buffer.isBuffer(value) ? value : JSON.stringify(value);
211	  return request(port, { method: 'POST', path: '/api/bookings', headers, body });
212	}
213	
214	export const getBookings = async (port, query = '') =>
215	  (await request(port, { path: `/api/bookings${query}` })).json.bookings;
216	
217	/**
218	 * Writes raw bytes to a socket and resolves to everything the server sent back
219	 * once it closes the connection (send `Connection: close`).
220	 */
221	export function rawRequest(port, data) {
222	  return new Promise((resolve, reject) => {
223	    const socket = connect(port, '127.0.0.1');
224	    socket.setTimeout(REQUEST_TIMEOUT_MS, () => socket.destroy(new Error('raw request got no full reply')));
225	    const chunks = [];
226	    socket.on('data', (c) => chunks.push(c));
227	    socket.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
228	    socket.on('error', reject);
229	    socket.write(data);
230	  });
231	}
232	
233	/** Opens a socket and returns it plus a getter for the bytes received so far. */
234	export function openSocket(port) {
235	  return new Promise((resolve, reject) => {
236	    const socket = connect(port, '127.0.0.1', () => resolve({ socket, received: () => text }));
237	    let text = '';
238	    socket.setEncoding('utf8');
239	    socket.on('data', (d) => (text += d));
240	    socket.on('error', reject);
241	  });
242	}
243	
244	/** Resolves true when 127.0.0.1:<port> can be bound right now. */
245	export function isPortFree(port) {
246	  return new Promise((resolve) => {
247	    const probe = createNetServer();
248	    probe.once('error', () => resolve(false));
249	    probe.listen(port, '127.0.0.1', () => probe.close(() => resolve(true)));
250	  });
251	}
252	
253	/** Binds a port (0 = any) on 127.0.0.1 and returns { port, close() }. */
254	export function occupyPort(port = 0) {
255	  return new Promise((resolve, reject) => {
256	    const blocker = createNetServer();
257	    blocker.once('error', reject);
258	    blocker.listen(port, '127.0.0.1', () =>
259	      resolve({
260	        port: blocker.address().port,
261	        close: () => new Promise((done) => blocker.close(() => done())),
262	      }),
263	    );
264	  });
265	}
266	
267	export const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
