15	/** Asserts a clean one-line startup failure; `stderr` (optional) is the exact expected text. */
16	function assertFailure(r, stderr) {
17	  assert.strictEqual(r.code, 1);
18	  assert.strictEqual(r.stdout, '');
19	  assert.match(r.stderr, /^[^\n]+\n$/);
20	  assert.ok(!r.stderr.includes('\n    at '), 'stderr has a stack trace');
21	  if (stderr !== undefined) assert.strictEqual(r.stderr, stderr);
22	}
