41	/** Starts on a fixed PORT (unset when undefined) and returns stdout after listening. */
42	async function listenLine(cwd, port, dataFile) {
43	  const handle = spawnServer({ cwd, env: { PORT: port, DATA_FILE: dataFile } });
44	  try {
45	    for (let i = 0; i < 500 && !handle.stdout().includes('\n'); i++) {
46	      if (handle.child.exitCode !== null) break;
47	      await delay(10);
48	    }
49	    return handle.stdout();
50	  } finally {
51	    handle.child.kill();
52	    await handle.exited;
53	  }
54	}
