71	describe('PORT=0', () => {
72	  test('prints exactly one listening line and nothing else', async () => {
73	    const dir = await freshDir();
74	    await withServer({ cwd: dir, env: { DATA_FILE: sub('none.json') } }, async (s) => {
75	      const m = LISTEN_RE.exec(s.stdout());
76	      assert.ok(m, 'listening line');
77	      assert.ok(s.port > 0);
78	      assert.strictEqual(Number(m[1]), s.port);
79	      assert.strictEqual((await request(s.port, { path: '/api/rooms' })).status, 200);
80	      assert.strictEqual((await request(s.port, { path: '/nope' })).status, 404);
81	      assert.strictEqual((await postBooking(s.port, '{bad')).status, 400);
82	      assert.strictEqual((await request(s.port, { method: 'PUT', path: '/api/rooms' })).status, 405);
83	      const line = s.stdout();
84	      assert.strictEqual(line, `listening on http://127.0.0.1:${s.port}\n`);
85	      assert.strictEqual(s.stderr(), '');
