163	describe('no listening on data failure', () => {
164	  test('nobody can connect while the server dies', async () => {
165	    const port = await freePort();
166	    const dir = await freshDir();
167	    await writeFile(join(dir, 'empty.json'), '');
168	    const handle = spawnServer({ cwd: dir, env: { PORT: String(port), DATA_FILE: 'empty.json' } });
169	    let done = false;
170	    let connected = false;
171	    handle.exited.then(() => (done = true));
172	    while (!done) {
173	      await new Promise((resolve) => {
174	        const s = connect(port, '127.0.0.1');
175	        s.once('connect', () => { connected = true; s.destroy(); resolve(); });
176	        s.once('error', () => resolve());
177	      });
178	      await delay(10);
179	    }
180	    const { code } = await handle.exited;
181	    assert.strictEqual(connected, false);
182	    assert.strictEqual(code, 1);
183	    assert.strictEqual(handle.stdout(), '');
184	    assert.strictEqual(handle.stderr(), msg('empty.json'));
185	  });
