188	describe('DATA_FILE default and relative resolution', () => {
189	  const seeded = { id: 1, ...booking() };
190	  const next = booking({ start: '10:00', end: '11:00' });
191	
192	  /** Seeds `file` (relative to a fresh dir), runs server with env, checks load and save. */
193	  async function loadAndSave(file, env, savedName) {
194	    const dir = await freshDir();
195	    const target = join(dir, file);
196	    await mkdir(join(target, '..'), { recursive: true });
197	    await writeStore(target, [seeded], 5);
198	    await withServer({ cwd: dir, env }, async (s) => {
199	      assert.deepStrictEqual(await getBookings(s.port), [seeded]);
200	      const res = await postBooking(s.port, next);
201	      assert.strictEqual(res.status, 201);
202	      assert.strictEqual(res.json.id, 5);
203	    });
204	    const saved = JSON.parse(await readFile(join(dir, savedName ?? file), 'utf8'));
205	    assert.deepStrictEqual(saved.bookings.map((b) => b.id), [1, 5]);
206	    assert.strictEqual(saved.nextId, 6);
207	    return dir;
208	  }
