260	describe('unreadable data file', () => {
261	  const b = (o = {}) => ({ id: 1, ...booking(), ...o });
262	  const store = (o = {}) => JSON.stringify({ nextId: 3, bookings: [b()], ...o });
263	  const cases = {
264	    empty: '',
265	    'whitespace only': '  \n',
266	    'not json': 'not json',
267	    truncated: '{"nextId":1,',
268	    null: 'null',
269	    array: '[]',
270	    zero: '0',
271	    string: '"x"',
272	    'empty object': '{}',
273	    'only nextId': '{"nextId":1}',
274	    'only bookings': '{"bookings":[]}',
275	    'extra top key': '{"nextId":1,"bookings":[],"x":1}',
276	    'nextId string': store({ nextId: '3' }),
277	    'nextId 0': store({ nextId: 0 }),
278	    'nextId 1.5': store({ nextId: 1.5 }),
279	    'bookings object': store({ bookings: {} }),
280	    'missing end': store({ bookings: [(({ end, ...r }) => r)(b())] }),
281	    'extra booking key': store({ bookings: [b({ x: 1 })] }),
